public class ArgumentImplTest{
private static final String OPTION_NAME = "test-option";
    private static final String OPTION_DESCRIPTION = "test-description";
    private static final int OPTION_MIN = 1;
    private static final int OPTION_MAX = 5;
    private static final char INITIAL_SEPARATOR = ',';
    private static final char SUBSEQUENT_SEPARATOR = ';';
    private static final String CONSUME_REMAINING = "--";
    private static final List<String> DEFAULT_VALUES = Collections.emptyList();
    private static final int ID = 1;

    private ArgumentImpl argumentImpl;
    private WriteableCommandLine commandLine;
    private Option option;
    private ListIterator<String> arguments;

    @Before
    public void setup() throws Exception {
        argumentImpl = new ArgumentImpl(OPTION_NAME, OPTION_DESCRIPTION, OPTION_MIN, OPTION_MAX, INITIAL_SEPARATOR, SUBSEQUENT_SEPARATOR, null, CONSUME_REMAINING, DEFAULT_VALUES, ID);
        commandLine = mock(WriteableCommandLine.class);
        option = mock(Option.class);
        arguments = Collections.emptyList().listIterator();
    }

    @After
    public void teardown() throws Exception {
    }

    @Test
    public void testProcessValues_ConsumeRemaining() throws Exception {
        when(arguments.hasNext()).thenReturn(true).thenReturn(false);
        when(arguments.next()).thenReturn(CONSUME_REMAINING);
        when(commandLine.getUndefaultedValues(option)).thenReturn(Collections.emptyList());
        argumentImpl.processValues(commandLine, arguments, option);
        verify(commandLine, never()).addValue(option, anyString());
    }

    @Test
    public void testProcessValues_LooksLikeOption() throws Exception {
        when(arguments.hasNext()).thenReturn(true).thenReturn(false);
        when(arguments.next()).thenReturn("-test");
        when(commandLine.looksLikeOption(anyString())).thenReturn(true);
        when(commandLine.getUndefaultedValues(option)).thenReturn(Collections.emptyList());
        argumentImpl.processValues(commandLine, arguments, option);
        verify(commandLine, never()).addValue(option, anyString());
    }

    @Test
    public void testProcessValues_SplitValues() throws Exception {
        when(arguments.hasNext()).thenReturn(true).thenReturn(false);
        when(arguments.next()).thenReturn("a;b;c");
        when(commandLine.getUndefaultedValues(option)).thenReturn(Collections.emptyList());
        argumentImpl.processValues(commandLine, arguments, option);
        verify(commandLine, times(3)).addValue(option, anyString());
    }

    @Test
    public void testProcessValues_SimpleValue() throws Exception {
        when(arguments.hasNext()).thenReturn(true).thenReturn(false);
        when(arguments.next()).thenReturn("test-value");
        when(commandLine.getUndefaultedValues(option)).thenReturn(Collections.emptyList());
        argumentImpl.processValues(commandLine, arguments, option);
        verify(commandLine).addValue(option, "test-value");
    }

    @Test(expected = OptionException.class)
    public void testProcessValues_TooManyValues() throws Exception {
        when(arguments.hasNext()).thenReturn(true).thenReturn(true).thenReturn(false);
        when(arguments.next()).thenReturn("a").thenReturn("b");
        when(commandLine.getUndefaultedValues(option)).thenReturn(Collections.emptyList());
        argumentImpl.setMaximum(1);
        argumentImpl.processValues(commandLine, arguments, option);
    }

    @Test
    public void testStripBoundaryQuotes() {
        assertEquals("\"test\"", argumentImpl.stripBoundaryQuotes("\"test\""));
        assertEquals("test", argumentImpl.stripBoundaryQuotes("test"));
    }

    @Test
    public void testGetPreferredName() {
        assertEquals(OPTION_NAME, argumentImpl.getPreferredName());
    }

    @Test
    public void testGetDescription() {
        assertEquals(OPTION_DESCRIPTION, argumentImpl.getDescription());
    }

    @Test
    public void testGetMinimum() {
        assertEquals(OPTION_MIN, argumentImpl.getMinimum());
    }

    @Test
    public void testGetMaximum() {
        assertEquals(OPTION_MAX, argumentImpl.getMaximum());
    }

    @Test
    public void testGetInitialSeparator() {
        assertEquals(INITIAL_SEPARATOR, argumentImpl.getInitialSeparator());
    }

    @Test
    public void testGetSubsequentSeparator() {
        assertEquals(SUBSEQUENT_SEPARATOR, argumentImpl.getSubsequentSeparator());
    }

    @Test
    public void testGetConsumeRemaining() {
        assertEquals(CONSUME_REMAINING, argumentImpl.getConsumeRemaining());
    }

    @Test
    public void testGetDefaultValues() {
        assertEquals(DEFAULT_VALUES, argumentImpl.getDefaultValues());
    }

    @Test
    public void testGetValidator() {
        assertNull(argumentImpl.getValidator());
    }
}
